for(const engine of ['bias.validate','gpumd.sampling'])test(engine+' complete scientific input receipt is independent of target/AI/sharing and binary acknowledgement is metadata only',async()=>{const f=await fixture(engine),i=await f.service.inspect({taskId:'same-task'},{});assert.equal(i.runtimeReceiptSha,null);assert.equal(i.targetConfirmationRequired,true);const binary=i.entries.find(e=>e.binary),r=await f.service.read({taskId:'same-task',snapshotId:i.snapshotId,entryId:binary.id},{});assert.equal(r.text,null);assert.equal(r.evidence,'metadata-only-current-producer-not-ABI');assert.equal(r.canConfirm,false);for(const e of i.entries.filter(e=>!e.binary)){const v=await f.service.read({taskId:'same-task',snapshotId:i.snapshotId,entryId:e.id},{});assert.equal(v.complete,true);assert.equal(typeof v.text,'string');}const v=await f.service.confirm({taskId:'same-task',snapshotId:i.snapshotId},{});assert.equal(v.status,'confirmed');assert.equal(f.receipts.size,1);assert.equal(f.task().review.status,'not_run');assert.equal(f.task().customCv.sharing.codex,false);assert.equal(f.task().authoring.environmentId,'authoring-CPU-env');assert.equal(f.task().localTargetReview.status,'stale');assert.equal(f.service.authority(f.task()).kind,'local-human');assert.equal((await f.service.verify('same-task')).data.engine,engine);assert.equal(f.calls.some(c=>/runtime|prepare|submit|sharing/.test(c.url)),false);await assert.rejects(f.service.verifyPrepared('same-task',{},{}),/target confirmation is unavailable/);});
